package patterns2;

public class AlphaRevSquare {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		
		for(int k=5;k>=1;k--) {
			
			for(char ch='E';ch>='A';ch--) {
				System.out.print(ch);
			}
			
			System.out.println();
		}

	}

}

